    const CBezierCurve& c2 = path.back();
    C3DVector expect = c1.Point4 - c1.Point3; for (int k = 0; k < 10; ++k) expect *= 0.5f;
    if (!near(c2.Point2.X, c1.Point4.X + expect.X) || !near(c2.Point2.Z, c1.Point4.Z + expect.Z)) ++fails;
